1	// content_erp.js —— ERP（赛狐 Sellfox）页面内操作，照搬 automation/erp.py。
2	// 由 background 注入到 sellfox.com 的所有 frame；只有承载订单表(vxe)的那个 frame 会真正干活，
3	// 其余 frame 的 dispatch 返回 null，被 background 过滤掉。
4	// 每个 op 把过程日志 push 进 L，随结果一起返回，由 background 转发到 popup 实时显示。
5	window.__HWC_ERP = window.__HWC_ERP || (function () {
6	  const H = window.__HWC;
7	  const FILTER_TEMPLATE = "未取消等待发货";
8	
9	  // 该 frame 是否承载订单业务视图？（有 vxe 表格 或 待处理/物流下单 相关 DOM）
10	  function isErpFrame() {
11	    return !!(document.querySelector(".vxe-table, .vxe-header--column") ||
12	              H.findByExactText("物流下单") ||
13	              H.qsa("*").some((e) => e.children.length === 0 && H.norm(e.innerText) === "待处理"));
14	  }
15	
16	  function dismissNotifications() {
17	    try { H.qsa(".el-notification").forEach((e) => e.remove()); } catch (e) {}
18	  }
19	
20	  // 等模板 popover 与 loading 遮罩都消失再操作。实测坑(2026-07-15)：选中筛选模板后，模板 popover
21	  // 残留 + 列表刷新 loading 遮罩，会让紧接着的渠道 input 点击弹不开渠道下拉（单例 popover 被占/
22	  // 遮罩拦点）——现象=模板成功那次渠道三次全未弹开、模板失败那次渠道反而能开（强相关）。
23	  const BLOCKER_SEL = ".el-popover, .select-menu, .search_more_temp_new, .el-loading-mask, .loading-indicator-overlay, .vxe-loading--wrapper";
24	  async function waitPageSettle(timeout = 6000) {
25	    await H.waitFor(() => !H.qsa(BLOCKER_SEL).some((p) => H.isVisible(p)), { timeout, interval: 300 });
26	  }
27	  function visibleBlockers() {
28	    return [...new Set(H.qsa(BLOCKER_SEL).filter((e) => H.isVisible(e))
29	      .map((e) => (typeof e.className === "string" ? e.className : "").split(" ")[0]).filter(Boolean))];
30	  }
31	
32	  async function dismissAlertModal(L) {
33	    for (let i = 0; i < 3; i++) {
34	      let closed = false;
35	      for (const t of ["稍后处理", "关闭", "我知道了", "取消"]) {
36	        const b = H.qsa(".el-dialog button, .el-message-box button")
37	          .find((x) => H.isVisible(x) && H.norm(x.innerText) === H.norm(t));
38	        if (b) { H.realClick(b); closed = true; await H.sleep(800); break; }
39	      }
40	      if (!closed) break;
41	    }
42	  }
43	
44	  async function gotoView(name, L) {
45	    const el = H.findByExactText(name);
46	    if (!el) { L.push(`[ERP] 未找到视图入口：${name}`); return false; }
47	    H.realClick(el);
48	    await H.sleep(3000);
49	    L.push(`[ERP] 切换到视图：${name}`);
50	    return true;
51	  }
52	
53	  // 需求1：选筛选模板（排除取消/退款/换货/禁处理单）。⚠️实测选模板会重置渠道筛选，
54	  // 故调用方必须【先选模板，再筛渠道】，让渠道筛选最后生效（安全底线）。
55	  async function selectFilterTemplate(name, L) {
56	    if (!name) return true;
57	    dismissNotifications();
58	    // 触发器直接用 class 定位（探测实证 reference class=search_more_temp_reference）——比 findByExactText
59	    // 文本匹配可靠：页面别处也有「筛选模板」文字（如"更多筛选"区），findByExactText 取 y 最靠上易选错、
60	    // 点了不弹 popover（实测 run 里三次重试都没弹开=定位错了触发器）。兜底再退回叶子文本匹配。
61	    const trigger = document.querySelector(".search_more_temp_reference")
62	      || H.qsa("span, div, a, button").find((e) => H.isVisible(e) && e.children.length === 0 && H.norm(e.innerText) === "筛选模板")
63	      || H.findByExactText("筛选模板");
64	    if (!trigger) { L.push("[ERP] 未找到『筛选模板』触发控件"); return false; }
65	    // 模板选项异步渲染 + 合成点击偶发不生效（实测探测两次一次弹开一次没弹）。轮询等选项出现、
66	    // 最多重试 3 轮点击，别固定 sleep 后就读。只匹配叶子(children.length===0)——探测确认
67	    // 「未取消等待发货」是 cls="" 独立叶子 span，不限叶子会误命中包含它的容器。
68	    const findOpt = () => H.qsa("span, div, li, a")
69	      .find((e) => H.isVisible(e) && e.children.length === 0 && H.norm(e.innerText) === H.norm(name));
70	    let opt = null;
71	    for (let attempt = 0; attempt < 3 && !opt; attempt++) {
72	      H.realClick(trigger);
73	      opt = await H.waitFor(() => findOpt(), { timeout: 4000, interval: 300 });
74	      if (!opt) { L.push(`[ERP] 筛选模板选项未出现(第${attempt + 1}次)，重试…`); await H.sleep(600); }
75	    }
76	    if (!opt) {
77	      L.push(`[ERP] 未找到筛选模板选项：${name}`);
78	      // 关键：找不到也要按 Esc 关掉筛选模板弹层，否则它是 single_el_popover 单例弹层，
79	      // 残留开着会导致下一步点渠道 input 只关旧弹层、不弹渠道下拉（实测渠道选项为空）。
80	      try { document.body.dispatchEvent(new KeyboardEvent("keydown", { key: "Escape", bubbles: true })); } catch (e) {}
81	      await H.sleep(400);
82	      return false;
83	    }
84	    H.realClick(opt);
85	    await H.sleep(1500);
86	    // 主动关闭模板 popover（Element el-popover 选项点选后不一定自动关；残留会占用单例弹层机制、
87	    // 导致下一步渠道 input 点击只被消费为"关模板"而不弹渠道下拉=实测渠道三次未弹开）。
88	    try { document.body.dispatchEvent(new KeyboardEvent("keydown", { key: "Escape", bubbles: true })); } catch (e) {}
89	    try { document.body.click(); } catch (e) {}
90	    await waitPageSettle();
91	    L.push(`[ERP] 已选择筛选模板：${name}`);
92	    return true;
93	  }
94	
95	  // 渠道筛选。触发 input[placeholder*='渠道'] -> 弹层 span.main_label 精确匹配 -> 确定。
96	  // 返回 {ok, available}。available = 找不到时下拉里实际可选渠道（便于判断是漏筛还是本就没单）。
97	  async function filterByChannel(channel, L) {
98	    if (!channel) return { ok: true };
99	    dismissNotifications();
100	    // 先按 Esc 清掉可能残留的弹层（如上一步筛选模板未关的 popover）。渠道弹层是 single_el_popover
101	    // 单例机制：若有旧弹层开着，点渠道 input 只会关旧弹层、不弹渠道下拉 → 选项为空（实测）。
102	    try { document.body.dispatchEvent(new KeyboardEvent("keydown", { key: "Escape", bubbles: true })); } catch (e) {}
103	    await H.sleep(400);
104	    // 点渠道 input 前先等页面稳定（模板 popover/loading 遮罩残留会让下拉弹不开）。
105	    await waitPageSettle();
106	    if (!document.querySelector("input[placeholder*='渠道']")) { L.push("[ERP] 未找到渠道筛选输入框"); return { ok: false, available: [] }; }
107	    // 渠道选项异步加载(虚拟滚动 vue-recycle-scroller) + 合成点击偶发不生效；且实测「模板一应用→渠道
108	    // 三次全不弹开且 blockers=[]」→ 疑模板刷新使工具栏重渲染、旧 input 引用失效。故【每轮重新抓 input】
109	    // + focus+click(探测证实 focus+click 也能弹开)，未弹开时打细诊断(connected/disabled/下拉容器数)。
110	    // 【自适应点法】独立探测总在"模板应用后"这步超时(页面卡顿)，故把"试多种点法"直接内建到生产流程：
111	    // 依次尝试 5 种点法，哪种让 span.main_label 冒出来就用哪种、并记录点法名（下次日志即知哪种有效）。
112	    // 病根候选：模板应用后渠道 el-popover 触发被抑制；不同点法(双击/focus/点外层 popover_trigger)或能破。
113	    // 关键实测(2026-07-15)：模板应用后点渠道，弹层【确实开了】(el-popover+select-menu 可见)，但里面
114	    // span.main_label【空】=选项没加载出来。故区分「弹层开」与「选项到位」：弹层一开就耐心等选项(8s，
115	    // 不急着换点法/不 Escape 打断加载)；等够还空就 dump 弹层内部结构，定性是"加载中/暂无/虚拟滚动没渲染"。
116	    const readLabels = () => H.qsa("span.main_label").filter((e) => H.isVisible(e));
117	    const ddOpen = () => H.qsa(".el-popover, .select-menu").some((e) => H.isVisible(e));
118	    const chan = () => document.querySelector("input[placeholder*='渠道']");
119	    const openers = [
120	      { name: "realClick", fn: () => H.realClick(chan()) },
121	      { name: "双击", fn: async () => { H.realClick(chan()); await H.sleep(300); H.realClick(chan()); } },
122	      { name: "focus+click", fn: () => { const i = chan(); try { i.focus(); } catch (e) {} H.realClick(i); } },
123	      { name: "popover_trigger", fn: () => { const t = chan() && chan().closest(".popover_trigger"); if (t) H.realClick(t); } },
124	      { name: "select-container", fn: () => { const t = chan() && chan().closest(".select-container"); if (t) H.realClick(t); } },
125	    ];
126	    let labels = [];
127	    let usedOpener = "";
128	    for (const op of openers) {
129	      if (!chan()) break;
130	      try { await op.fn(); } catch (e) {}
131	      const opened = await H.waitFor(() => (ddOpen() || readLabels().length) ? true : null, { timeout: 2500, interval: 200 });
132	      if (!opened) {
133	        L.push(`[ERP] 渠道点法「${op.name}」弹层未开，换下一种…`);
134	        try { document.body.dispatchEvent(new KeyboardEvent("keydown", { key: "Escape", bubbles: true })); } catch (e) {}
135	        await H.sleep(400);
136	        continue;
137	      }
138	      // 弹层开了，耐心等选项加载（虚拟滚动/异步）
139	      const got = await H.waitFor(() => { const l = readLabels(); return l.length ? l : null; }, { timeout: 8000, interval: 400 });
140	      if (got && got.length) { labels = got; usedOpener = op.name; break; }
141	      // 弹层开着但选项一直空 → dump 内部结构诊断（换点法无意义，是数据/加载问题）
142	      const dd = H.qsa(".el-popover, .select-menu").find((e) => H.isVisible(e));
143	      const info = dd ? {
144	        文本: (dd.innerText || "").replace(/\s+/g, " ").trim().slice(0, 140),
145	        有搜索框: !!dd.querySelector("input"),
146	        有虚拟滚动: !!dd.querySelector(".vue-recycle-scroller"),
147	        子class: [...new Set([...dd.querySelectorAll("*")].slice(0, 200)
148	          .map((e) => (typeof e.className === "string" ? e.className : "").split(" ")[0]).filter(Boolean))].slice(0, 12),
149	      } : "弹层已消失";
150	      L.push(`[ERP] 渠道点法「${op.name}」弹层开但选项空，弹层内部=${JSON.stringify(info)}`);
151	      break;   // 弹层能开、问题在选项数据，换点法没用，停止
152	    }
153	    if (!labels.length) {
154	      L.push(`[ERP] 渠道下拉未取到选项，跳过本渠道（可见弹层/遮罩=${JSON.stringify(visibleBlockers())}）`);
155	      return { ok: false, available: [] };
156	    }
157	    L.push(`[ERP] 渠道下拉已弹开（点法=${usedOpener}，${labels.length}项）`);
158	    // span.main_label 精确匹配（别用包含——订单行物流信息列也含渠道文字会误点）
159	    const picked = labels.find((el) => (el.innerText || "").trim() === channel);
160	    if (!picked) {
161	      const available = [...new Set(labels.map((e) => (e.innerText || "").trim()).filter(Boolean))].sort();
162	      L.push(`[ERP] 未找到渠道选项：${channel}；当前下拉可选渠道=${JSON.stringify(available)}`);
163	      try { document.body.dispatchEvent(new KeyboardEvent("keydown", { key: "Escape", bubbles: true })); } catch (e) {}
164	      return { ok: false, available };
165	    }
166	    H.realClick(picked);
167	    L.push(`[ERP] 渠道选中：${channel}`);
168	    await H.sleep(500);
169	    // 确定：只在可见弹层容器内找按钮，避免误点页面别处常驻的“确定/确认”（旧 `, button` 是全页面匹配）。
170	    let okBtn = null;
171	    for (const p of H.qsa(".el-popper, .el-select-dropdown, .el-popover").filter((c) => H.isVisible(c))) {
172	      okBtn = H.qsa("button", p).find((b) => H.isVisible(b) && ["确定", "确认"].includes(H.norm(b.innerText)));
173	      if (okBtn) break;
174	    }
175	    if (okBtn) H.realClick(okBtn);
176	    else L.push("[ERP] ⚠️ 未在弹层内找到渠道『确定』按钮（可能选中即生效，继续）");
177	    await H.sleep(2500);
178	    return { ok: true };
179	  }
180	
181	  // 订单总数：.total_style 取最大（异步加载，轮询到 >0 或超时）。兜底 .parentRowGroup 计数。
182	  async function countOrders(L) {
183	    const read = () => {
184	      const a = H.qsa(".total_style")
185	        .map((e) => parseInt((e.innerText || "0").replace(/\D/g, ""), 10)).filter((x) => !isNaN(x));
186	      return a.length ? Math.max(...a) : 0;
187	    };
188	    for (let i = 0; i < 5; i++) {
189	      const n = read();
190	      if (n > 0) return n;
191	      await H.sleep(1000);
192	    }
193	    return H.qsa(".parentRowGroup").length;
194	  }
195	
196	  // vxe 表头全选 + 校验确有行被勾选。
197	  async function selectAll(L) {
198	    const th = document.querySelector(".vxe-header--column.col--checkbox .vxe-cell--checkbox");
199	    if (!th) { L.push("[ERP] 未找到 vxe 表头全选框"); return false; }
200	    if ((th.getAttribute("class") || "").includes("is--disabled")) {
201	      L.push("[ERP] 表头全选框禁用（可能无数据）"); return false;
202	    }
203	    H.realClick(th);
204	    await H.sleep(1500);
205	    const checked = H.qsa(".vxe-body--row.row--checked, .vxe-cell--checkbox.is--checked").length;
206	    if (!checked) { L.push("[ERP] 全选后未检测到勾选行"); return false; }
207	    L.push(`[ERP] 已全选，勾选标记数≈${checked}`);
208	    return true;
209	  }
210	
211	  // 工具栏「物流下单」按钮（排除行内同名按钮，取 y 最靠上的可见按钮）。
212	  function findToolbarButton(text) {
213	    return H.findByExactText(text, {
214	      selectors: "button, .el-button, .base_button_comp, .myj-btn, [class*=btn]",
215	      excludeRowSel: ".vxe-body--row",
216	    });
217	  }
218	
219	  function parseResultText(txt) {
220	    if (!txt) return { success: null, fail: null, fail_orders: [], text: "" };
221	    const ms = txt.match(/成功[:：]?\s*(\d+)/);
222	    const mf = txt.match(/失败[:：]?\s*(\d+)/);
223	    const orders = [...new Set((txt.match(/\bP[0-9A-Z]{9,15}\b/g) || []))];
224	    return { success: ms ? +ms[1] : null, fail: mf ? +mf[1] : null, fail_orders: orders, text: txt };
225	  }
226	
227	  async function readResultDialog(L) {
228	    let txt = null;
229	    await H.waitFor(() => {
230	      const dlg = H.qsa(".el-dialog__wrapper .el-dialog, .el-message-box")
231	        .find((d) => H.isVisible(d));
232	      if (dlg) { txt = (dlg.innerText || "").trim(); return true; }
233	      return false;
234	    }, { timeout: 30000, interval: 1000 });
235	    if (txt) L.push("[ERP] 物流下单结果:\n" + txt.slice(0, 800));
236	    // 关闭：只点可见弹窗内的关闭/确定按钮
237	    const btn = H.qsa(".el-dialog__wrapper button, .el-message-box__wrapper button").find((b) =>
238	      H.isVisible(b) && ["关闭", "确定", "知道了", "ok", "OK"].includes(H.norm(b.innerText)));
239	    if (btn) H.realClick(btn);
240	    else try { document.body.dispatchEvent(new KeyboardEvent("keydown", { key: "Escape", bubbles: true })); } catch (e) {}
241	    await H.sleep(1000);
242	    return parseResultText(txt);
243	  }
244	
245	  // ===== 主 op：物流下单 =====
246	  async function placeOrder({ channel, dry }) {
247	    const L = [];
248	    await dismissAlertModal(L);
249	    dismissNotifications();
250	    if (!(await gotoView("待处理", L))) return { logs: L, error: "无法进入待处理视图" };
251	
252	    // 先选模板 -> 再筛渠道（顺序不可反：模板会重置渠道筛选，让渠道最后生效=安全底线）
253	    if (!(await selectFilterTemplate(FILTER_TEMPLATE, L)))
254	      L.push("[ERP] ⚠️ 筛选模板未选中，继续（渠道筛选仍保证范围，仅少了取消/退款单排除）");
255	
256	    if (channel) {
257	      const f = await filterByChannel(channel, L);
258	      if (!f.ok) {
259	        L.push(`[ERP] 渠道筛选未成功(${channel})，为避免全量误下单，跳过本渠道`);
260	        return { logs: L, count: 0, channelFilterFailed: true, available: f.available || [] };
261	      }
262	    }
263	
264	    const n = await countOrders(L);
265	    L.push(`[ERP] 待处理订单 共 ${n} 条${channel ? `（渠道：${channel}）` : ""}`);
266	    if (n === 0) return { logs: L, count: 0, success: 0, fail: 0, fail_orders: [] };
267	
268	    if (!(await selectAll(L))) return { logs: L, count: n, error: "全选失败" };
269	
270	    if (dry) {
271	      L.push(`[ERP][DRY] 将点击【物流下单】处理 ${n} 条（已跳过实际点击）`);
272	      return { logs: L, count: n, dry: true };
273	    }
274	
275	    const btn = findToolbarButton("物流下单");
276	    if (!btn) return { logs: L, count: n, error: "未定位到工具栏物流下单按钮" };
277	    H.realClick(btn);
278	    L.push(`[ERP] 已点击工具栏【物流下单】，处理 ${n} 条`);
279	    await H.sleep(3000);
280	    const r = await readResultDialog(L);
281	    if (r.fail) L.push(`[ERP] ⚠️ 物流下单失败 ${r.fail} 单：${JSON.stringify(r.fail_orders)}`);
282	    return { logs: L, count: n, success: r.success, fail: r.fail, fail_orders: r.fail_orders, result_text: r.text };
283	  }
284	
285	  // ===== op：获取跟踪号（三方仓 > 待更新 > 手动更新）=====
286	  async function updateStatus() {
287	    const L = [];
288	    if (!(await gotoView("三方仓", L))) return { logs: L, error: "进三方仓失败" };
289	    if (!(await gotoView("待更新", L))) return { logs: L, error: "待更新子标签失败" };
290	    const n = await countOrders(L);
291	    if (!n) { L.push("[ERP] 待更新 0 条"); return { logs: L, total: 0, got: 0, fail: 0 }; }
292	    if (!(await selectAll(L))) return { logs: L, error: "待更新全选失败" };
293	    const btn = H.findByExactText("手动更新", {
294	      selectors: "button, .el-button, .base_button_comp, [class*=btn]", excludeRowSel: ".vxe-body--row" });
295	    if (!btn) return { logs: L, total: n, error: "无手动更新按钮" };
296	    H.realClick(btn);
297	    L.push(`[ERP] 已全选 ${n} 条并点【手动更新】，拉取跟踪号中…`);
298	    let final = null;
299	    await H.waitFor(() => {
300	      const d = H.qsa(".el-dialog, .el-message-box").find((e) => H.isVisible(e));
301	      if (d) { final = (d.innerText || "").trim(); if (final.includes("获取完成") || final.includes("100%")) return true; }
302	      return false;
303	    }, { timeout: 60000, interval: 1000 });
304	    const res = { logs: L, total: null, got: null, fail: null, text: final };
305	    if (final) {
306	      const mt = final.match(/共\s*(\d+)\s*个?包裹/), mg = final.match(/已获取\s*(\d+)/), mf = final.match(/(\d+)\s*个?获取失败/);
307	      res.total = mt ? +mt[1] : null; res.got = mg ? +mg[1] : null; res.fail = mf ? +mf[1] : null;
308	      L.push(`[ERP] 状态更新结果: 共${res.total} 已获取${res.got} 失败${res.fail}`);
309	    }
310	    const cb = H.qsa(".el-dialog button, .el-message-box button").find((b) =>
311	      H.isVisible(b) && ["关闭", "确定", "ok", "OK"].includes(H.norm(b.innerText)));
312	    if (cb) H.realClick(cb);
313	    return res;
314	  }
315	
316	  async function dispatch(msg) {
317	    if (!isErpFrame()) return null;   // 非订单表 frame，交给其它 frame
318	    try {
